+    {
+        var service = new Mock<IOrderService>();
+        service.Setup(s => s.UpdateStatusAsync(7, "Shipped", It.IsAny<CancellationToken>()))
+               .ReturnsAsync(true);
+        var controller = new OrdersController(service.Object);
+
+        var result = await controller.UpdateStatus(7, new UpdateOrderStatusRequest("Shipped"));
